import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.ScriptMessage{Identifier: "endstone:ping", Data: []byte("hello")}
PING = bytes.fromhex("0d656e6473746f6e653a70696e670568656c6c6f")

# generated by gophertunnel b8bd735:
# &packet.ScriptMessage{Data: []byte(strings.Repeat("x", 200))}
LONG_VALUE = bytes.fromhex("00c801") + bytes.fromhex("78") * 200

GOLDENS = [
    pytest.param(v2225.ScriptMessagePacket(message_id="endstone:ping", message_value="hello"), PING, id="ping"),
    pytest.param(
        v2225.ScriptMessagePacket(message_value="x" * 200),
        LONG_VALUE,
        id="200-byte-value-takes-a-two-byte-length",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_script_message_is_packet_177(version):
    assert version.PACKETS[177] is version.ScriptMessagePacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_script_message_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_script_message_decodes_from_its_golden(packet, golden):
    assert v2225.ScriptMessagePacket.from_bytes(golden) == packet
